import React from "react";

const TransactionList = ({ transactions }) => {
  return (
    <div>
      <h3>Transactions</h3>

      {transactions.length === 0 ? (
        <p>No expenses added yet</p>
      ) : (
        transactions.map((t, index) => (
          <p key={index}>
            {t.title} - ₹{t.amount}
          </p>
        ))
      )}
    </div>
  );
};

export default TransactionList;
